module TopModule (
    input  logic        clk,
    input  logic        reset,
    input  logic [7:0]  in,
    output logic [23:0] out_bytes,
    output logic        done
);

    typedef enum logic [1:0] {
        S_SEARCH = 2'b00,
        S_RECV2  = 2'b01,
        S_RECV3  = 2'b10,
        S_DONE   = 2'b11
    } state_t;

    state_t state;
    logic [7:0] b1, b2, b3;
    logic [23:0] out_bytes_reg;
    logic done_reg;

    always_ff @(posedge clk) begin
        if (reset) begin
            state         <= S_SEARCH;
            b1            <= 8'h0;
            b2            <= 8'h0;
            b3            <= 8'h0;
            out_bytes_reg <= 24'h0;
            done_reg      <= 1'b0;
        end else begin
            case (state)
                S_SEARCH: begin
                    done_reg <= 1'b0;
                    if (in[3]) begin
                        b1    <= in;
                        state <= S_RECV2;
                    end
                end
                S_RECV2: begin
                    done_reg <= 1'b0;
                    b2       <= in;
                    state    <= S_RECV3;
                end
                S_RECV3: begin
                    done_reg <= 1'b0;
                    b3       <= in;
                    state    <= S_DONE;
                end
                S_DONE: begin
                    done_reg      <= 1'b1;
                    out_bytes_reg <= {b1, b2, b3};
                    if (in[3]) begin
                        b1    <= in;
                        state <= S_RECV2;
                    end else begin
                        state <= S_SEARCH;
                    end
                end
            endcase
        end
    end

    assign done = done_reg;
    assign out_bytes = out_bytes_reg;

endmodule

