module tb_TopModule;
    logic        clk;
    logic        reset;
    logic [7:0]  in;
    logic [23:0] out_bytes;
    logic        done;

    TopModule dut (
        .clk(clk),
        .reset(reset),
        .in(in),
        .out_bytes(out_bytes),
        .done(done)
    );

    // Clock generator: 10ns period (5ns high, 5ns low)
    initial clk = 0;
    always #5 clk = ~clk;

    initial begin
        // Initialize signals
        reset = 1;
        in = 8'h00;
        #12; // Wait past first rising edge at 5ns with reset=1

        reset = 0;

        // Apply sequence matching the example waveform
        // t = 15ns (clk posedge)
        in = 8'h2c; #10;
        // t = 25ns
        in = 8'h81; #10;
        // t = 35ns
        in = 8'h09; #10;
        // t = 45ns -> done should be 1, out_bytes = 2c8109, in = 6b
        in = 8'h6b; 
        #2;
        if (done !== 1 || out_bytes !== 24'h2c8109) begin
            $display("FAIL at t=45: done=%b (exp 1), out_bytes=%h (exp 2c8109)", done, out_bytes);
            $display("SELFTEST FAIL: mismatch at message 1");
            $finish;
        end
        #8; // finish 45ns cycle

        // t = 55ns
        in = 8'h0d; #10;
        // t = 65ns
        in = 8'h8d; #10;
        // t = 75ns -> done should be 1, out_bytes = 6b0d8d, in = 6d
        in = 8'h6d;
        #2;
        if (done !== 1 || out_bytes !== 24'h6b0d8d) begin
            $display("FAIL at t=75: done=%b (exp 1), out_bytes=%h (exp 6b0d8d)", done, out_bytes);
            $display("SELFTEST FAIL: mismatch at message 2");
            $finish;
        end
        #8;

        // t = 85ns
        in = 8'h12; #10;
        // t = 95ns
        in = 8'h01; #10;
        // t = 105ns -> done should be 1, out_bytes = 6d1201, in = 0d
        in = 8'h0d;
        #2;
        if (done !== 1 || out_bytes !== 24'h6d1201) begin
            $display("FAIL at t=105: done=%b (exp 1), out_bytes=%h (exp 6d1201)", done, out_bytes);
            $display("SELFTEST FAIL: mismatch at message 3");
            $finish;
        end
        #8;

        // t = 115ns
        in = 8'h76; #10;
        // t = 125ns
        in = 8'h3d; #10;
        // t = 135ns -> done should be 1, out_bytes = 0d763d, in = ed
        in = 8'hed;
        #2;
        if (done !== 1 || out_bytes !== 24'h0d763d) begin
            $display("FAIL at t=135: done=%b (exp 1), out_bytes=%h (exp 0d763d)", done, out_bytes);
            $display("SELFTEST FAIL: mismatch at message 4");
            $finish;
        end
        #8;

        // t = 145ns
        in = 8'h8c; #10;
        // t = 155ns
        in = 8'hf9; #10;
        // t = 165ns -> done should be 1, out_bytes = ed8cf9, in = ce
        in = 8'hce;
        #2;
        if (done !== 1 || out_bytes !== 24'hed8cf9) begin
            $display("FAIL at t=165: done=%b (exp 1), out_bytes=%h (exp ed8cf9)", done, out_bytes);
            $display("SELFTEST FAIL: mismatch at message 5");
            $finish;
        end
        #8;

        // t = 175ns
        in = 8'hc5; #10;
        // t = 185ns
        in = 8'haa; #10;

        $display("SELFTEST PASS");
        $finish;
    end
endmodule

