        .clk(clk),
        .reset(reset),
        .in(in),
        .out_bytes(out_bytes),
        .done(done)
    );

    initial clk = 0;
    always #5 clk = ~clk;

    initial begin
        reset = 1;
        in = 8'h00;
        @(posedge clk);
        @(posedge clk);
        reset = 0;

        // t = 15ns posedge: in = 2c
        in = 8'h2c;
        @(posedge clk);

        // t = 25ns posedge: in = 81
        in = 8'h81;
        @(posedge clk);

        // t = 35ns posedge: in = 09
        in = 8'h09;
        @(posedge clk);

        // t = 45ns posedge: in = 6b. Message 1 complete!
        in = 8'h6b;
        #1; // sample after posedge
        if (done !== 1 || out_bytes !== 24'h2c8109) begin
            $display("FAIL at msg 1: done=%b (exp 1), out_bytes=%h (exp 2c8109)", done, out_bytes);
            $display("SELFTEST FAIL");
