        end
        @(posedge clk);

        // t = 55ns posedge: in = 0d
        in = 8'h0d;
        #1;
        if (done !== 0) begin
            $display("FAIL at t=55: done should be 0, got %b", done);
            $display("SELFTEST FAIL");
            $finish;
        end
        @(posedge clk);

        // t = 65ns posedge: in = 8d
        in = 8'h8d;
        @(posedge clk);

        // t = 75ns posedge: in = 6d. Message 2 complete!
        in = 8'h6d;
