        // t = 95ns posedge: in = 01
        in = 8'h01;
        @(posedge clk);

        // t = 105ns posedge: in = 0d. Message 3 complete!
        in = 8'h0d;
        #1;
        if (done !== 1 || out_bytes !== 24'h6d1201) begin
            $display("FAIL at msg 3: done=%b (exp 1), out_bytes=%h (exp 6d1201)", done, out_bytes);
            $display("SELFTEST FAIL");
            $finish;
        end
        @(posedge clk);

        // t = 115ns posedge: in = 76
        in = 8'h76;
        @(posedge clk);

        // t = 125ns posedge: in = 3d
        in = 8'h3d;
        @(posedge clk);

        // t = 135ns posedge: in = ed. Message 4 complete!
        in = 8'hed;
        #1;
        if (done !== 1 || out_bytes !== 24'h0d763d) begin
            $display("FAIL at msg 4: done=%b (exp 1), out_bytes=%h (exp 0d763d)", done, out_bytes);
            $display("SELFTEST FAIL");
            $finish;
        end
        @(posedge clk);

        // t = 145ns posedge: in = 8c
        in = 8'h8c;
        @(posedge clk);

        // t = 155ns posedge: in = f9
        in = 8'hf9;
        @(posedge clk);

        // t = 165ns posedge: in = ce. Message 5 complete!
        in = 8'hce;
        #1;
        if (done !== 1 || out_bytes !== 24'hed8cf9) begin
            $display("FAIL at msg 5: done=%b (exp 1), out_bytes=%h (exp ed8cf9)", done, out_bytes);
            $display("SELFTEST FAIL");
            $finish;
        end
        @(posedge clk);

        $display("SELFTEST PASS");
        $finish;
